using System;

public struct Quote
{
    public string Id;
    public string Text;
    public string Author;
}

public static class FrenchQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eug%C3%A8ne_Labiche", Text = "Politesse et bonne humeur avec tout le monde, et respect aux femmes de chambre…", Author = "Eugène Labiche" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Katharine_Hepburn", Text = "Je n'ai aucune crainte de la mort. Ce doit être merveilleux, comme un long sommeil. Et puis, regardons les choses en face: ce qui compte c'est ce qu'on fait de sa vie.", Author = "Katharine Hepburn" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dobermann", Text = "Inspecteur Sauveur Cristini: Ils ont tous des têtes de camés, ça s'défonce, ça s'flingue ... c'est la mode, avec moi tout ces bouffons y s'raient déjà morts.", Author = "Dobermann" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%96d%C3%B6n_von_Horv%C3%A1th", Text = "Rien ne donne autant le sentiment de l'infinitude que la bêtise.", Author = "Ödön von Horváth" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vera_Songwe", Text = "Ce nouveau deal (proposé par Emmanuel Macron) doit être un peu plus retravaillé avec les dirigeants africains pour qu'il s'inscrive dans une nouveauté, pour s'adapter aux besoins très différents de cette jeune Afrique.", Author = "Vera Songwe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bernadette_Essossimna_Legzim-Balouki", Text = "Le Togo ne ménagera aucun effort dans le soutien de vos actions pour la promotion du secteur privé sous régional, qui est le moyen sûr de lutter contre la pauvreté et le chômage.", Author = "Bernadette Essossimna Legzim-Balouki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Bon%2C_la_Brute_et_le_Truand", Text = "Tu vois, le monde se divise en deux catégories: ceux qui ont un pistolet chargé et ceux qui creusent. Toi, tu creuses.", Author = "Le Bon, la Brute et le Truand" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Flore_Hazoum%C3%A9", Text = "Tu n'as plus rien, tu n'es plus rien, tu n'as plus un sou.", Author = "Flore Hazoumé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coco_Argent%C3%A9e", Text = "je travaille beaucoup et je suis exigeante envers moi-même et envers mon travail.", Author = "Coco Argentée" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amina_Tidjani_Yaya", Text = "À travers cette campagne sur la scolarisation des filles, nous voudrions bien se battre chaque jour pour que chaque petite fille et chaque adolescente puissent aller et rester à l’école, puis au collège et au lycée. C’est pour nous la pierre angulaire du progrès social et économique.", Author = "Amina Tidjani Yaya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mahomet", Text = "Celui qui s’engage dans une voie à la recherche d’un savoir, Dieu lui facilitera une voie vers le Paradis.", Author = "Mahomet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pauvret%C3%A9", Text = "Il me semble qu’à égalité d’esprit et de lumières, l’homme né riche ne doit jamais connaître aussi bien que le pauvre, la nature, le cœur humain et la société. C’est que, dans le moment où l’autre plaçait une jouissance, le second se consolait par une réflexion.", Author = "Pauvreté" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bandy_Kiki", Text = "Début 2017, alors que les troubles politiques s’intensifiaient dans les régions anglophones du Cameroun, mes opinions en tant que blogueur sur les crises ont fini par faire de moi un objet de critiques publiques et d’intimidation sur Internet.", Author = "Bandy Kiki" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sac_d%27os", Text = "Quand on gagne son pain quotidien en labourant les terres de l'imaginaire, la ligne qui sépare ce qui est de ce qui semble être est encore plus ténue.", Author = "Sac d'os" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Pierre_Dupuy", Text = "Le monde a vécu l'événement du 11 septembre moins comme l'inscription dans le réel de quelque chose d'insensé, donc d'impossible, que comme l'irruption du possible dans l'impossible.", Author = "Jean-Pierre Dupuy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fania_No%C3%ABl", Text = "L'afroféminisme fait partie des Féminismes Noirs, mais les Féminismes Noirs ne se résument pas à l'afroféminisme.", Author = "Fania Noël" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chili", Text = "Chili, pur est ton ciel bleuté;\npures aussi sont les brises qui te survolent,\net tes campagnes bordées de fleurs\nsont la copie joyeuse de l’Éden.\nMajestueuse est la montagne blanche\nque le Seigneur t’a donné comme place forte,\net cette mer qui te baigne tranquillement\nte promet la splendeur future.", Author = "Chili" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Theresa_May", Text = "Je veux que la Grande-Bretagne soit la grande méritocratie du monde – un pays où chacun a une chance équitable d’aller aussi loin que son talent et son travail acharné le permettent.", Author = "Theresa May" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Myst%C3%A8re_de_la_chambre_jaune_%28film%29", Text = "Le narrateur: Nulle présence sous le lit, nulle présence derrière les meubles, nulle présence.\nLe juge De Marquet: [avec délectation] Nulle présence...", Author = "Le Mystère de la chambre jaune (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rosemonde_G%C3%A9rard", Text = "Ce n'est qu'en pardonnant qu'on ne se trompe pas", Author = "Rosemonde Gérard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Sarkozy", Text = "David, nous, on te soutient à mort pour cette campagne!", Author = "Jean Sarkozy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karl_Schiller", Text = "Autant de marché que possible, autant d’État que nécessaire.", Author = "Karl Schiller" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dikkenek", Text = "Annule-moi un peu ce rendez-vous avec ces deux imbéciles de l'école de TV. J'ai pas le temps, j'ai matériellement pas le temps de faire ça.\nDes trous de cul pareil ça m'intéresse pas.", Author = "Dikkenek" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Assassin%28s%29", Text = "Wagner: Dites moi, vous avez un frère?\nVidal: Un frère? Non.\nWagner: Pas de frère? Vous avez un fils?\nVidal: Oui j'ai un fils…\nWagner: Ah oui, ben c'est lui qui nous envoie…\nVidal: Mon fils, mais c'est pas possible…\nWagner : Mais si mon ami c'est possible, tout est possible…", Author = "Assassin(s)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cameron_Diaz", Text = "Ce que j’ai appris en ayant eu plusieurs relations, c’est qu’il ne faut pas en parler à la presse! Mais qu’est-ce que je trouve sexy? Je trouve sexy la confiance en soi chez un homme, une vraie confiance en soi, pas une confiance machiste et gonflée à bloc.", Author = "Cameron Diaz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mireille_Boccara", Text = "La mort d'un enfant nous laisse les mains vides et l'esprit déchiré de questions sans réponse.", Author = "Mireille Boccara" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ngon%C3%A9_Ndour", Text = "Une société ultra moderne de gestion collective, fruit d’une gestion durable, collective, participative et démocratique de ses membres, pour ses membres et par ses membres.", Author = "Ngoné Ndour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dieudonn%C3%A9_Niangouna", Text = "L’intellectuel est un poisson qui suit la tempête dans le fleuve.", Author = "Dieudonné Niangouna" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Francisco_de_Goya", Text = "La duchesse d'Albe vient d'entrer dans mon atelier et a voulu que je lui peignisse le visage au pastel. Peindre ainsi sur le vif, mon cher;  charmante occupation, que je préfère aux études sur le mannequin.", Author = "Francisco de Goya" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne-Gabriel_Meusnier_de_Querlon", Text = "Adieu, plaiſant pays de France,\nÔ ma patrie, La plus chérie\nQui as nourri ma jeune enfance!\nAdieu, France, adieu mes beaux jours.", Author = "Anne-Gabriel Meusnier de Querlon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cameroun", Text = "Camerounais, Camerounaises, le Cameroun est libre.", Author = "Cameroun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Hobbit", Text = "Dans un trou vivait un hobbit. Ce n'était pas un trou déplaisant, sale et humide, rempli de bouts de vers et d'une atmosphère suintante, non plus qu'un trou sec, nu, sablonneux, sans rien pour s'asseoir ni sur quoi manger: c'était un trou de hobbit, ce qui implique le confort.", Author = "Le Hobbit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Edgar_Faure", Text = "La seconde blessure de la décolonisation, pour nous peut-être la plus grave, c’est le sentiment de l’injustice. Nous avons l’impression que nous sommes trahis et reniés, que nous sommes victimes d’une ingratitude parce que nous avons apporté beaucoup de bien.", Author = "Edgar Faure" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Meslier", Text = "La religion est une vraie pépinière de fanatiques: c'est véritablement le théâtre où ils jouent le mieux leurs personnages", Author = "Jean Meslier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Psych%C3%A9d%C3%A9lique", Text = "Ironiquement, ce n'est peut-être pas les jeunes qui ont souffert de l'opprobre publique à cause de leur association aux psychédéliques; peut être que ce sont les psychédéliques qui ont souffert de leur association avec de jeunes perturbateurs.", Author = "Psychédélique" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Harry_Crews", Text = "Même les croque-morts se sentent bien seuls, parfois.", Author = "Harry Crews" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Muir", Text = "Chacun d'entre nous a besoin de beauté comme de pain, de places pour jouer et de lieux de prière, d'endroits où la nature puisse le guérir et se réjouir, et le fortifier dans son corps et son âme.", Author = "John Muir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gauz", Text = "Comprenez bien, les enfants, on ne peut pas être indépendants quand même ce qu'on mange vient de ceux qui nous aliènent.", Author = "Gauz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mort_sur_le_Nil", Text = "Je trouve pas ça normal qu'elle ait une telle allure! L'argent plus la beauté, c'est trop pour une seule bonne femme. [...] Cette fille là, elle a tout. Y a pas de justice.", Author = "Mort sur le Nil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maria_Winkelmann", Text = "Maintenant, je passe par un désert aride, et parce que... l'eau est rare... le goût est amer.", Author = "Maria Winkelmann" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mati_Diop", Text = "Avant de parler de la forme, je revendique la dimension politique du geste. Donner une forme inattendue et libre à la question des restitutions, c'est politique. Les restitutions ne doivent pas être appréhendées seulement par les politiciens, les universitaires ou le milieu de l'art.", Author = "Mati Diop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/V%C3%A9ronique_Kanor", Text = "Je suis le vernis cassé. Je suis la misère délabrée, le poisson mal vidé. Je suis ma case en tôle, une jarre d’or qui n’existe pas. Je suis la nouvelle venue à godillots, celle qui ne sait pas faire la bise avec le front, celle qui revient au pays prénatal sans avoir composté l’aller.", Author = "Véronique Kanor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Friends", Text = "Ross: Mais j'ai pas envie d'être célibataire, je veux me remarier tout de suite!\n(Rachel entre dans le Central Perk en robe de mariée)\nChandler s'écriant vers la porte: Moi tout de suite je veux un million de dollars!", Author = "Friends" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jolie_Kenda", Text = "Mon idéal se traduit par le souci du bien-être communautaire. J'aime écouter les autres et j'aime bien me faire le porte-parole des désœuvrés.", Author = "Jolie Kenda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charles_Baudelaire", Text = "Le vin est semblable à l'homme: on ne saura jamais jusqu'à quel point on peut l'estimer et le mépriser, l'aimer et le haïr, ni de combien d'actions sublimes ou de forfaits monstrueux il est capable. Ne soyons donc pas plus cruels envers lui qu'envers nous-mêmes, et traitons-le comme notre égal.", Author = "Charles Baudelaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Romy_et_Michelle%2C_10_ans_apr%C3%A8s", Text = "Cowboy: Tu avais raison j'étais un paysan arriéré, un trou du cul… quoique j'ai jamais baisé un mouton, ni ma sœur d'ailleurs.\nHeather Mooney: Pourquoi, ils couraient trop vite pour toi?", Author = "Romy et Michelle, 10 ans après" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diane_von_F%C3%BCrstenberg", Text = "Ce n'est pas que je suis arrogante, mais avec l'âge, on acquiert une certaine sagesse", Author = "Diane von Fürstenberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sha%C3%AFne_Cassim", Text = "Je pense que la destruction de l'être passe beaucoup par le langage. Le langage érige des murs. C'est une cathédrale de mots qui empêchent, qui interdisent, où il n'y a pas de libre arbitre.", Author = "Shaïne Cassim" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Osakwe", Text = "Les gouvernements doivent faire un bien meilleur travail en tant que facilitateurs d'entreprises et ne pas être un obstacle pour les PME, qui, comme nous le savons tous, sont les moteurs de la croissance et de l'emploi dans toute économie.", Author = "Ada Osakwe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nnedi_Okorafor", Text = "Tenir la vérité cachée revient à mentir.", Author = "Nnedi Okorafor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stanislas-Andr%C3%A9_Steeman", Text = "C'est le lot des innocents que d'être soupçonnés par la justice et celui des fripouilles que de courir en liberté.", Author = "Stanislas-André Steeman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89cole_nationale_d%27administration", Text = "Je suis un rescapé. J'ai failli sombrer. J'ai fait l'ENA. ce n'est pas une école, c'est un moule, un laminoir sémantique qui vous broie: vous y entrez avec trois mille mots, vous en sortez avec trente seulement, le cerveau formaté, hors de vos neurones et le cœur vide.", Author = "École nationale d'administration" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Waris_Dirie", Text = "Quand on parcourt le chemin de la vie, bravant des tempêtes, jouissant du soleil, se retrouvant souvent dans l'œil du cyclone, on ne survit qu'à force de volonté.", Author = "Waris Dirie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nouria_Benghabrit-Remaoun", Text = "Ce bruit ne m’empêchera pas d’avancer et personne n’a le monopole du nationalisme en Algérie.", Author = "Nouria Benghabrit-Remaoun" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nawal_El_Saadawi", Text = "L'homme s'est mis dans une situation délicate lorsqu'il a décidé que la femme était innée et passive.", Author = "Nawal El Saadawi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Louise_Mumbu", Text = "N’écoute pas ta mère!", Author = "Marie-Louise Mumbu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Ange_Lukiana_Mufwankolo", Text = "Il s'agit de la hauteur, de la régularité et de la capacité d'atteindre les bénéficiaires. L'instrument de mesure sera le contrat de performance évalué mensuellement", Author = "Marie-Ange Lukiana Mufwankolo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Patrick_Castro", Text = "C’est vrai que je n’ai pas fait faire de coups de barrière... mais j’ai toujours raseté les taureaux arrêtés.", Author = "Patrick Castro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Guignols_de_l%27info", Text = "PPD: Monsieur de Villiers, un mot peut être?\nPhilippe de Villiers: Hum hum. Savez-vous que sous ce plateau il y a 28 mosquées clandestines et deux ateliers de fabrique de couscoussières explosives et de merguez à l'anthrax.\nPPD: Oui bon, c'était pas la peine en fait.", Author = "Les Guignols de l'info" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Organisation_des_Nations_unies", Text = "Je commence à comprendre le mécanisme de l'hypocrisie mondiale dont les Nations unies sont devenues les doctrinaires et l'instrument. L'interdiction de voir a un sens, un but: elle permet l'interdiction d'agir.", Author = "Organisation des Nations unies" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louisa_May_Alcott", Text = "J’ai souvent le sentiment que je vendrais volontiers mon âme à Satan en échange d’une année de liberté.", Author = "Louisa May Alcott" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott/Guethenoc", Text = "Attention, attention… il va y arriver un moment où il y a des granges qui vont se mettre à flamber, faudra pas demander d’où ça vient!", Author = "Kaamelott/Guethenoc" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Daerden", Text = "Si on tait aujourd'hui encore ce qu'on a déjà passé sous silence hier, comment alors empêcher les gens de dire demain ce qu'on ne leur a jamais laissé entendre?", Author = "Michel Daerden" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatoumatta_Bah-Barrow", Text = "La protection des enfants, y compris ceux qui sont en situation de déplacement, est essentielle pour notre société et, en tant que Première Dame, je m'engage à défendre la protection des enfants en Gambie.", Author = "Fatoumatta Bah-Barrow" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mounia_Youssef", Text = "L’art a un grand impact sur les individus dans la société dans laquelle nous vivons. Les choses changent grâce à l’art, les mentalités changent.", Author = "Mounia Youssef" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dixi%C3%A8me_Docteur", Text = "Le Docteur: Des nouvelles dents? C'est bizarre. Alors, où en étais-je...? Ah oui, c'est vrai! Barcelone, c'est ça?", Author = "Dixième Docteur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mar%C3%ADa_Nsu%C3%A9_Ang%C3%BCe", Text = "La femme est comme un enfant. Elle n’a pas conscience de ce qu’est la fidélité… Elle est comme les feuilles d’un arbre, elle aime selon la direction du vent.", Author = "María Nsué Angüe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jo%C3%ABlle_Ecormier", Text = "Le Grand Tamarinier touche sans couler et s'affiche avant tout comme un conte philosophique profondément optimiste", Author = "Joëlle Ecormier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Teta_Diana", Text = "La musique est un langage qui traverse les frontières et atteint l'âme", Author = "Teta Diana" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mich%C3%A8le_Alliot-Marie", Text = "Les règles étaient difficiles à fixer. Elles ont été changées au dernier moment, celles que l'on m'avait indiquées la veille au soir ne sont pas celles qui ont été appliquées. J'aurais pu dire que je m'en vais, ce n'est pas mon genre.", Author = "Michèle Alliot-Marie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aiguille", Text = "J'ai déjà dit, en racontant ma rencontre avec lui, que le crâne de Freud ressemblait à un escargot de Bourgogne. La conséquence est évidente: si on veut manger sa pensée il faut la sortir avec une aiguille. Alors elle sort tout entière.", Author = "Aiguille" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adaptation", Text = "Je préfère toujours le livre à son adaptation en BD ou au cinéma. En refermant un livre, on en garde des images, donc nul besoin d'aller en chercher ailleurs.", Author = "Adaptation" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Otto_Klemperer", Text = "La musique est l’art des arts, l’art métaphysique par excellence. Là où les mots s’achèvent, commence la musique. Et où la musique s’achève-t-elle? La musique est infinie. Elle est le langage de l’âme.", Author = "Otto Klemperer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Avarice", Text = "L'avarice est un beau péché recouvert d'algues et d'incrustations soleilleuses.", Author = "Avarice" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Scholastique_Dianzinga", Text = "Ainsi, les femmes n'ont jamais reculé devant les situations graves et, à toutes les époques elles ont apporté leur contribution.", Author = "Scholastique Dianzinga" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Arnothy", Text = "La moralité est faite pour les pauvres, pour mieux les tenir.", Author = "Christine Arnothy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Foudre", Text = "Nous prîmes congé de lui le matin, d'un simple regard qui signifiait à la fois que nous n'appartenions plus à la vie et que, si nous revenions jamais de notre nouvel état, ce serait à la façon des sourciers pour toucher le ciel de notre baguette de foudre.", Author = "Foudre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Astou_N%27Diaye", Text = "Chers frères et sœurs il faut finir le lycée au moins et sachez que sport et études vont de pair ici et il n’y a pas d’autre moyens.", Author = "Astou N'Diaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bertrand_Piccard", Text = "Je ne vois pas comment nous pourrions être responsables de ce que l'existence nous fait subir. En revanche, nous sommes pleinement responsables de notre manière d'y réagir.", Author = "Bertrand Piccard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sahndra_Fon_Dufe", Text = "Si vous voulez changer de peau parce que vous ressentez une certaine pression, rappelez-vous que la vie ne s'arrête pas au lycée ou à l'université. Il existe un vaste monde dans lequel vous pouvez vous intégrer parfaitement.", Author = "Sahndra Fon Dufe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pete_Dexter", Text = "Y en a, ils se rendent pas compte de leur bonheur. Ils se rendent pas compte qu'en demandant ce qu'on a pas, on commence à renoncer à ce qu'on a.", Author = "Pete Dexter" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arielle_Kitio_Tsamo", Text = "Pour réussir, je pense que chaque jeune se concentre sur sa passion, qu’il travaille intelligemment et qu’il soit positif...J’applique la philosophie des 4 P à savoir, la Passion, le Partage, la Persévérance, la Positivité, les People.", Author = "Arielle Kitio Tsamo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mahawa_Bangoura", Text = "Le nouveau défi collectif est de faire émerger l’image d’un monde d’égalité, de dignité, d’équité et de solidarité internationale, traduite en une coopération économique et sociale et en un véritable ajustement social, plaçant l’être humain au centre.", Author = "Mahawa Bangoura" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Didier_van_Cauwelaert", Text = "À trente ans on inhume encore une promesse; à cinquante on enterre des concessions.", Author = "Didier van Cauwelaert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Julie_Andrews", Text = "Madame était sûre que j'étais capable de chanter Mozart et Rossini, mais, pour être honnête, je ne l'ai jamais été.", Author = "Julie Andrews" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9mocrite", Text = "La parole est l'ombre de l'action.", Author = "Démocrite" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Protection_de_monument_historique", Text = "Aux États-Unis, ce qu'ils appellent monuments historiques, conseillés par d'importants écriteaux bruns, c'est par exemple un pan de mur de moulin qui a soixante-cinq ans.", Author = "Protection de monument historique" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Lovelace", Text = "Je crois que je possède une singulière combinaison de qualités, qui semble précisément ajustées pour me prédisposer à devenir une exploratrice des réalités cachées de la Nature.", Author = "Ada Lovelace" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Suzette_Sandoz", Text = "Le mariage gay pourrait mener à la fin de notre civilisation", Author = "Suzette Sandoz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Edernac", Text = "C'est vrai parce qu'il n'y a rien.", Author = "Pierre Edernac" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thierry_Maulnier", Text = "On est aliéné dès qu'on est un objet dans la liberté d'autrui.", Author = "Thierry Maulnier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nicole_Belloubet", Text = "La fonction d'enseignant n'est plus suffisament attractive", Author = "Nicole Belloubet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Magda_Gessler", Text = "Pourquoi empoisonnez-vous les gens?!", Author = "Magda Gessler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joseph_Ki-Zerbo", Text = "Si nous nous couchons, nous sommes morts.", Author = "Joseph Ki-Zerbo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rudy_Rucker", Text = "Les gens se sont interrogés sur les atomes bien des siècles avant que l'on ait eu espoir de détecter un atome individuel. Et si personne n'avait jamais parlé des atomes, on n'aurait jamais pu développer les moyens pour les détecter.", Author = "Rudy Rucker" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Prestige", Text = "Robert Angier: Jamais je ne pensais trouver une réponse au fond d'un verre de bière.\nCutter: Cela ne vous a pas empêché de chercher.", Author = "Le Prestige" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ursula_Burns", Text = "L'essentiel n'est pas de savoir si je suis noire ou blanche, c'est que je sois à la hauteur de la tâche.", Author = "Ursula Burns" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Miroir_qui_gla%C3%A7ait", Text = "Parce que je crois aussi que, souvent, les jeunes sont plus vifs à saisir la réalité des choses que les vieux. Comme ils manquent d'expérience, ils ne sont pas tentés de sortir des solutions toutes faites.", Author = "Le Miroir qui glaçait" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C._S._Lewis", Text = "Je suis un païen converti vivant au milieu de puritains apostats.", Author = "C. S. Lewis" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/A%C3%AFchatou_Ma%C3%AFnassara", Text = "Il ya un changement qui existe bel et bien qu’on le veuille ou pas. Donc, qu’on soit de la majorité ou de l’opposition, l’essentiel c’est d’aller vers l’intérêt du peuple", Author = "Aïchatou Maïnassara" }
    };
}